from typing import List, Dict, Any, Optional, Union
import re

# --- 字段校验 (Field Validation) ---

def is_valid_shard_id(shard: Any) -> bool:
    """
    校验分片ID是否为有效的整数格式（0-31）。
    """
    try:
        val = int(shard)
        return 0 <= val <= 31
    except (ValueError, TypeError):
        return False

def is_valid_latency(latency: Any) -> bool:
    """
    校验延迟值是否为非负整数。
    """
    try:
        val = int(latency)
        return val >= 0
    except (ValueError, TypeError):
        return False

def is_valid_hash(hash_str: Any) -> bool:
    """
    校验哈希字符串是否为有效的十六进制字符串（长度8）。
    """
    if not isinstance(hash_str, str):
        return False
    return bool(re.fullmatch(r'[0-9a-fA-F]{8}', hash_str))

def is_valid_event_id(event_id: Any) -> bool:
    """
    校验事件ID格式是否为 EV 后跟6位数字。
    """
    if not isinstance(event_id, str):
        return False
    return bool(re.fullmatch(r'EV\d{6}', event_id))

def is_valid_state(state: Any) -> bool:
    """
    校验状态字段是否为 'ok' 或 'error'。
    """
    return state in ('ok', 'error')

def validate_event_record(record: Dict[str, Any]) -> bool:
    """
    校验单条事件记录是否包含所有必要字段且格式正确。
    """
    required_fields = ['id', 'shard', 'latency_ms', 'state', 'hash']
    if not all(field in record for field in required_fields):
        return False

    if not is_valid_event_id(record['id']):
        return False
    if not is_valid_shard_id(record['shard']):
        return False
